import React, { useState } from "react";
import { useParams } from "react-router-dom";
import videosData from "../data/videosData";

const VideoPage = () => {
  const { id } = useParams();
  const course = videosData.find((c) => c.id === id);

  console.log("ID da rota:", id);
  console.log("Course encontrado:", course);

  const [currentModule, setCurrentModule] = useState(course?.modules[0]);

  if (!course) {
    return (
      <div className="min-h-screen flex items-center justify-center text-xl">
        ⚠️ Curso não encontrado
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center p-6">
      <h1 className="text-3xl font-semibold text-center mb-8">{course.title}</h1>
      <div className="flex w-full max-w-6xl bg-white rounded-lg shadow-lg overflow-hidden">
        <div className="w-1/4 bg-red-600 text-white p-6">
          <h2 className="text-xl font-semibold mb-6">MÓDULOS</h2>
          <ul>
            {course.modules.map((mod, index) => (
              <li
                key={index}
                onClick={() => setCurrentModule(mod)}
                className={`cursor-pointer mb-3 ${
                  currentModule?.file === mod.file ? "font-bold" : ""
                }`}
              >
                ✔️ {mod.title}
              </li>
            ))}
          </ul>
        </div>

        <div className="w-3/4 p-6">
          <video
            key={currentModule?.file}
            controls
            className="w-full h-96 rounded-lg shadow"
          >
            <source src={currentModule?.file} type="video/mp4" />
          </video>
          <p className="mt-4 text-lg font-medium">{currentModule?.title}</p>
        </div>
      </div>
    </div>
  );
};

export default VideoPage;
